];

const FlowRow: React.FC<{
  step: (typeof FLOW_STEPS)[number];
  index: number;
  delay: number;
}> = ({ step, index, delay }) => {
  const frame = useCurrentFrame();
  const { fps: vfps } = useVideoConfig();
  const p = springIn(frame, vfps, delay, "LIQUID");
  const isHighlight = step.status === "402";

  const drift = ambientDrift(frame, 0.8, 90 + index * 10, `row-${index}`);

  return (
    <div
      style={{
        opacity: p,
        transform: `translateX(${interpolate(p, [0, 1], [-40, 0])}px) translateY(${drift}px)`,
        display: "flex",
        alignItems: "center",
        gap: 28,
        padding: "22px 28px",
        backgroundColor: isHighlight
          ? COLORS.orangeTint
          : "rgba(255,255,255,0.04)",
        border: `1px solid ${isHighlight ? COLORS.orange : COLORS.border}`,
        borderRadius: 14,
        fontFamily: "Inter, sans-serif",
      }}
    >
      {/* Status badge */}
      <div
        style={{
          minWidth: 88,
          padding: "8px 14px",
          borderRadius: 8,
          backgroundColor: isHighlight
