          fontFamily: "monospace",
          fontSize: 22,
          fontWeight: 700,
          color: isHighlight ? "#000" : COLORS.textMuted,
          textAlign: "center",
          letterSpacing: "0.05em",
        }}
      >
        {step.status}
      </div>

      {/* Label + descriptor */}
      <div
        style={{
          display: "flex",
          flexDirection: "column",
          gap: 6,
          flex: 1,
          fontFamily: "Inter, sans-serif",
        }}
      >
        <div
          style={{
            fontFamily: "monospace",
            fontSize: 30,
            fontWeight: 600,
            color: step.color,
            letterSpacing: "-0.005em",
          }}
