  { label: "Real-time pricing data", price: "$0.01 / req", note: "Verified source" },
  { label: "AI inference call", price: "$0.04 / req", note: "GPU-backed" },
];

const SELL_ROWS = [
  { label: "Your Actor output", price: "$0.005 / call", note: "Auto-priced" },
  { label: "Curated dataset", price: "$0.50 / row", note: "On-demand" },
  { label: "Custom agent skill", price: "$0.10 / run", note: "Reusable" },
];

const MarketCard: React.FC<{
  side: "buy" | "sell";
  title: string;
  subtitle: string;
  rows: typeof BUY_ROWS;
  delay: number;
}> = ({ side, title, subtitle, rows, delay }) => {
  const frame = useCurrentFrame();
  const { fps: vfps, height } = useVideoConfig();
  const cardIn = springIn(frame, vfps, delay, "LIQUID");
  const driftY = ambientDrift(frame, 1.6, 120, `card-${side}`);

  const isSell = side === "sell";

  return (
    <div
      style={{
        opacity: cardIn,
        transform: `translateY(${interpolate(cardIn, [0, 1], [40, 0])}px) translateY(${driftY}px) scale(${interpolate(
          cardIn,
          [0, 1],
          [0.96, 1]
        )})`,
        backgroundColor: COLORS.card,
        border: `1px solid ${isSell ? COLORS.orange : COLORS.border}`,
        borderRadius: 20,
        padding: 36,
        display: "flex",
        flexDirection: "column",
        gap: 24,
        fontFamily: "Inter, sans-serif",
        position: "relative",
        overflow: "hidden",
      }}
    >
      {/* Subtle accent bar */}
      <div
        style={{
          position: "absolute",
          left: 0,
          top: 0,
          bottom: 0,
          width: 4,
          backgroundColor: isSell ? COLORS.orange : COLORS.border,
        }}
      />

      {/* Header */}
      <div
        style={{
          display: "flex",
          flexDirection: "column",
          gap: 8,
          fontFamily: "Inter, sans-serif",
        }}
      >
        <div
          style={{
            fontFamily: "monospace",
            fontSize: 18,
            color: isSell ? COLORS.orange : COLORS.textSubtle,
            letterSpacing: "0.18em",
            textTransform: "uppercase",
            fontWeight: 600,
          }}
        >
          {isSell ? "Sell side" : "Buy side"}
        </div>
        <div
          style={{
            fontFamily: "'GT Walsheim', Inter, sans-serif",
            fontSize: height * 0.038,
            fontWeight: 700,
            color: COLORS.text,
            letterSpacing: "-0.02em",
            lineHeight: 1.1,
          }}
        >
          {title}
        </div>
        <div
          style={{
            fontFamily: "Inter, sans-serif",
            fontSize: height * 0.019,
            color: COLORS.textMuted,
            lineHeight: 1.4,
          }}
        >
          {subtitle}
        </div>
      </div>

      {/* Divider */}
      <div
        style={{
          height: 1,
          backgroundColor: COLORS.border,
        }}
      />

      {/* Rows */}
      <div style={{ display: "flex", flexDirection: "column", gap: 14 }}>
        {rows.map((row, i) => {
          const rowP = staggeredSpring(
            frame,
            vfps,
            i,
            delay + 14,
            10,
            "GENTLE"
          );
          return (
            <div
              key={i}
              style={{
                opacity: rowP,
                transform: `translateX(${interpolate(rowP, [0, 1], [-20, 0])}px)`,
                display: "flex",
                alignItems: "center",
                gap: 16,
                padding: "16px 18px",
                backgroundColor: "rgba(255,255,255,0.04)",
                border: `1px solid ${COLORS.border}`,
                borderRadius: 12,
                fontFamily: "Inter, sans-serif",
              }}
            >
              {/* Check or arrow icon */}
              <svg width={20} height={20} viewBox="0 0 24 24">
                {isSell ? (
                  <path
                    d="M7 17 L17 7 M10 7 L17 7 L17 14"
                    stroke={COLORS.orange}
                    strokeWidth={2.5}
                    strokeLinecap="round"
                    strokeLinejoin="round"
                    fill="none"
                    strokeDasharray={30}
                    strokeDashoffset={interpolate(rowP, [0, 1], [30, 0])}
                  />
                ) : (
                  <path
                    d="M5 12.5 L10 17.5 L19 7"
                    stroke={COLORS.orange}
                    strokeWidth={2.75}
                    strokeLinecap="round"
                    strokeLinejoin="round"
                    fill="none"
                    strokeDasharray={28}
                    strokeDashoffset={interpolate(rowP, [0, 1], [28, 0])}
                  />
                )}
              </svg>

              <div style={{ flex: 1, fontFamily: "Inter, sans-serif" }}>
                <div
                  style={{
                    fontFamily: "Inter, sans-serif",
                    fontSize: 24,
                    fontWeight: 600,
                    color: COLORS.text,
                    letterSpacing: "-0.005em",
                  }}
                >
                  {row.label}
                </div>
                <div
                  style={{
                    fontFamily: "Inter, sans-serif",
                    fontSize: 18,
                    color: COLORS.textSubtle,
                    marginTop: 2,
                  }}
                >
                  {row.note}
                </div>
              </div>

              <div
                style={{
                  fontFamily: "monospace",
                  fontSize: 20,
                  fontWeight: 600,
                  color: isSell ? COLORS.orange : COLORS.textMuted,
                  letterSpacing: "-0.005em",
                }}
              >
                {row.price}
              </div>
            </div>
          );
        })}
      </div>
    </div>
  );
};

